async function png(bytes,max=2048){if(bytes.length>4*MiB||bytes.length<33||!bytes.slice(0,8).every((b,i)=>b===[137,80,78,71,13,10,26,10][i]))fail('需要有效的 PNG 图片。');const dv=new DataView(bytes.buffer,bytes.byteOffset,bytes.byteLength),w=dv.getUint32(16),h=dv.getUint32(20);if(!w||!h||w>max||h>max)fail('PNG 尺寸超出限制。');const url=await new Promise((res,rej)=>{const r=new FileReader();r.onload=()=>res(r.result);r.onerror=()=>rej(new Error('无法读取图片。'));r.readAsDataURL(new Blob([bytes],{type:'image/png'}));});await new Promise((res,rej)=>{const im=new Image();im.onload=()=>im.naturalWidth===w&&im.naturalHeight===h?res():rej(new Error('PNG 尺寸校验失败。'));im.onerror=()=>rej(new Error('PNG 图片无法解码。'));im.src=url;});return {url,width:w,height:h};}
async function readPet(file){const ext=file.name.split('.').pop().toLowerCase();if(file.size>(ext==='png'?2:5)*MiB)fail('静态 PNG 最大 2 MB；桌宠 ZIP 最大 5 MB。');const buffer=await file.arrayBuffer();if(ext==='png'){const im=await png(new Uint8Array(buffer),1024);return {url:im.url,name:file.name.replace(/\.png$/i,'').slice(0,40),frame:{width:im.width,height:im.height,columns:1,rows:1},animations:{idle:{frames:[0],fps:1,loop:true}},pixelated:false,static:true};}if(ext!=='zip')fail('请选择静态 PNG 或桌宠 ZIP。');const files=await unzip(buffer);let m;try{m=JSON.parse(new TextDecoder('utf-8',{fatal:true}).decode(files['manifest.json']));}catch{fail('manifest.json 不是有效 JSON。');}if(!safePath(m.image)||!files[m.image])fail('找不到 manifest 指定的 PNG。');if(Object.keys(files).some(k=>!['manifest.json',m.image,'LICENSE.txt'].includes(k)))fail('包内包含多余资源。');const im=await png(files[m.image]);m=validateManifest(m,im.width,im.height);return {...m,url:im.url};}
function frameNode(p){const d=document.createElement('div');d.className='sprite-frame';const scale=Math.min(112/p.frame.width,112/p.frame.height);d.style.width=p.frame.width*scale+'px';d.style.height=p.frame.height*scale+'px';d.style.backgroundImage='url("'+p.url+'")';d.style.backgroundSize=p.frame.width*p.frame.columns*scale+'px '+p.frame.height*p.frame.rows*scale+'px';d.dataset.w=p.frame.width*scale;d.dataset.h=p.frame.height*scale;return d;}
