function reduced(){return document.body.classList.contains('motion-off')||matchMedia('(prefers-reduced-motion: reduce)').matches;}
function renderPet(){clearTimeout(timer);step=0;holder.replaceChildren();defaultPet.toggleAttribute('hidden',!!current);holder.hidden=!current;el('pet').setAttribute('aria-label',(current?.name||'小团')+'，换一句鼓励语');el('idle').querySelector('.pet-hint').textContent=(current?.name||'小团')+' · 轻点换一句';if(!current)return;holder.classList.toggle('pixel',current.pixelated);const d=frameNode(current);holder.append(d);animate('idle',d);}
function animate(key,d){clearTimeout(timer);step=0;const p=current,a=p.animations[key]||p.animations.idle;function tick(){if(!current)return;const idx=a.frames[Math.min(step,a.frames.length-1)];paint(d,p,idx);if(document.hidden||reduced()||panelHidden())return;step++;if(step>=a.frames.length){if(a.loop===false&&key==='tap'){animate('idle',d);return;}if(a.loop===false)return;step=0;}if(a.frames.length>1)timer=setTimeout(tick,1000/a.fps);}tick();}
