setting.addEventListener('click',open);el('pet-select').addEventListener('click',()=>{if(busy)return;el('pet-file').value='';el('pet-file').click();});el('pet-file').addEventListener('change',async()=>{const f=el('pet-file').files[0];if(!f)return;const ticket=++selectionEpoch;busy=true;el('pet-confirm').disabled=true;el('pet-error').hidden=true;try{const candidate=await readPet(f);if(ticket!==selectionEpoch||!el('pet-dialog').open)return;pending=candidate;showPreview(pending);el('pet-summary').textContent=pending.name+' · '+(pending.static?'静态 PNG':pending.frame.columns+'×'+pending.frame.rows+' 帧网格 · '+pending.animations.idle.fps+' fps');el('pet-confirm').disabled=false;}catch(e){if(ticket!==selectionEpoch||!el('pet-dialog').open)return;pending=null;el('pet-error').textContent='导入失败：'+e.message+' 当前桌宠已保留。';el('pet-error').hidden=false;showPreview(current);}finally{busy=false;}});
el('pet-cancel').addEventListener('click',close);el('pet-dialog').addEventListener('cancel',()=>{selectionEpoch++;pending=null;clearTimeout(previewTimer);});el('pet-confirm').addEventListener('click',()=>{if(!pending)return;current=pending;pending=null;let ok=true;try{localStorage.setItem('kejian-pet-v1',JSON.stringify(current));}catch{ok=false;}close();renderPet();toast(ok?'桌宠已替换 · 你好，'+current.name:'桌宠已替换；资源较大，仅在本次页面保留');});el('pet-reset').addEventListener('click',()=>{current=null;try{localStorage.removeItem('kejian-pet-v1');}catch{}close();renderPet();toast('已恢复原创小团');});el('pet').addEventListener('click',()=>{if(current&&!reduced()){const d=holder.firstElementChild;if(d)animate('tap',d);}});
