try{const p=JSON.parse(localStorage.getItem('kejian-pet-v1')||'null');if(p&&typeof p.url==='string'&&p.url.startsWith('data:image/png;base64,')&&p.url.length<6*MiB){const w=p.frame?.width*p.frame?.columns,h=p.frame?.height*p.frame?.rows;if(p.static&&integer(p.frame.width,1,1024)&&integer(p.frame.height,1,1024)&&p.frame.columns===1&&p.frame.rows===1&&typeof p.name==='string')current={...p,animations:{idle:{frames:[0],fps:1,loop:true}}};else{validateManifest(p,w,h);current=p;}}}catch{}renderPet();
